=== FILE: axi4_lite_regs.v ===
`timescale 1ns / 1ps
// ---------------------------------------------------------------------------
// axi4_lite_regs
//
// Four 32-bit read/write registers behind an AXI4-Lite subordinate port.
// Implements microarchitecture.md (holding registers, no FSM, no skid buffer)
// for interface_spec.md.
//
//  * READY depends on state only:
//      awready = !aw_held && !bvalid
//      wready  = !w_held  && !bvalid
//      arready = !rvalid
//  * AW and W are independent; whichever arrives alone is held. The write
//    fires on the edge that completes the pair:
//      do_write = (aw_held || aw_hs) && (w_held || w_hs)
//  * One outstanding transaction per direction; response latency 1 cycle.
//  * Unmapped (misaligned) addresses answer SLVERR; unmapped writes change
//    nothing, unmapped reads return zero.
//  * aresetn: synchronous, active low.
// ---------------------------------------------------------------------------
module axi4_lite_regs #(
    parameter integer ADDR_WIDTH = 4,
    parameter integer DATA_WIDTH = 32
) (
    input  wire                      aclk,
    input  wire                      aresetn,

    input  wire [ADDR_WIDTH-1:0]     s_axil_awaddr,
    input  wire                      s_axil_awvalid,
    output wire                      s_axil_awready,

    input  wire [DATA_WIDTH-1:0]     s_axil_wdata,
    input  wire [(DATA_WIDTH/8)-1:0] s_axil_wstrb,
    input  wire                      s_axil_wvalid,
    output wire                      s_axil_wready,

    output reg  [1:0]                s_axil_bresp,
    output reg                       s_axil_bvalid,
    input  wire                      s_axil_bready,

    input  wire [ADDR_WIDTH-1:0]     s_axil_araddr,
    input  wire                      s_axil_arvalid,
    output wire                      s_axil_arready,

    output reg  [DATA_WIDTH-1:0]     s_axil_rdata,
    output reg  [1:0]                s_axil_rresp,
    output reg                       s_axil_rvalid,
    input  wire                      s_axil_rready
);

  localparam integer STRB_WIDTH  = DATA_WIDTH / 8;
  localparam [1:0]   RESP_OKAY   = 2'b00;
  localparam [1:0]   RESP_SLVERR = 2'b10;

  // -------------------------------------------------------------------------
  // State
  // -------------------------------------------------------------------------
  reg                  aw_held;    // write address accepted, waiting for W
  reg                  w_held;     // write data accepted, waiting for AW
  reg [ADDR_WIDTH-1:0] aw_addr_q;  // datapath: not reset (flag is)
  reg [DATA_WIDTH-1:0] w_data_q;   // datapath: not reset (flag is)
  reg [STRB_WIDTH-1:0] w_strb_q;   // datapath: not reset (flag is)

  reg [DATA_WIDTH-1:0] reg0;
  reg [DATA_WIDTH-1:0] reg1;
  reg [DATA_WIDTH-1:0] reg2;
  reg [DATA_WIDTH-1:0] reg3;

  reg [DATA_WIDTH-1:0] rd_word;

  // -------------------------------------------------------------------------
  // Handshakes and write pairing
  // -------------------------------------------------------------------------
  wire                  aw_hs;
  wire                  w_hs;
  wire                  ar_hs;
  wire                  do_write;
  wire [ADDR_WIDTH-1:0] wr_addr;
  wire [DATA_WIDTH-1:0] wr_data;
  wire [STRB_WIDTH-1:0] wr_strb;
  wire [DATA_WIDTH-1:0] wr_mask;
  wire                  wr_mapped;
  wire                  ar_mapped;
  wire                  wr_en;
  wire [1:0]            wr_idx;
  wire [1:0]            rd_idx;

  assign s_axil_awready = !aw_held && !s_axil_bvalid;
  assign s_axil_wready  = !w_held  && !s_axil_bvalid;
  assign s_axil_arready = !s_axil_rvalid;

  assign aw_hs = s_axil_awvalid && s_axil_awready;
  assign w_hs  = s_axil_wvalid  && s_axil_wready;
  assign ar_hs = s_axil_arvalid && s_axil_arready;

  assign do_write = (aw_held || aw_hs) && (w_held || w_hs);

  assign wr_addr = aw_held ? aw_addr_q : s_axil_awaddr;
  assign wr_data = w_held  ? w_data_q  : s_axil_wdata;
  assign wr_strb = w_held  ? w_strb_q  : s_axil_wstrb;

  // Mapped: word aligned and within the four-register window. With the
  // default ADDR_WIDTH of 4 the window term is always true; it keeps the
  // decode correct if the address is widened.
  assign wr_mapped = (wr_addr[1:0] == 2'b00) &&
                     ((wr_addr >> 4) == {ADDR_WIDTH{1'b0}});
  assign ar_mapped = (s_axil_araddr[1:0] == 2'b00) &&
                     ((s_axil_araddr >> 4) == {ADDR_WIDTH{1'b0}});

  assign wr_en  = do_write && wr_mapped;
  assign wr_idx = wr_addr[3:2];
  assign rd_idx = s_axil_araddr[3:2];

  // Byte mask from strobes: merge(old, data, strb) of the microarchitecture
  // is (old & ~mask) | (data & mask).
  genvar g;
  generate
    for (g = 0; g < STRB_WIDTH; g = g + 1) begin : g_mask
      assign wr_mask[g*8 +: 8] = {8{wr_strb[g]}};
    end
  endgenerate

  // -------------------------------------------------------------------------
  // Write address / data holding
  // -------------------------------------------------------------------------
  always @(posedge aclk) begin
    if (!aresetn) begin
      aw_held <= 1'b0;
    end else if (do_write) begin
      aw_held <= 1'b0;
    end else if (aw_hs) begin
      aw_held <= 1'b1;
    end
  end

  always @(posedge aclk) begin
    if (aw_hs && !do_write) begin
      aw_addr_q <= s_axil_awaddr;
    end
  end

  always @(posedge aclk) begin
    if (!aresetn) begin
      w_held <= 1'b0;
    end else if (do_write) begin
      w_held <= 1'b0;
    end else if (w_hs) begin
      w_held <= 1'b1;
    end
  end

  always @(posedge aclk) begin
    if (w_hs && !do_write) begin
      w_data_q <= s_axil_wdata;
      w_strb_q <= s_axil_wstrb;
    end
  end

  // -------------------------------------------------------------------------
  // Register file
  // -------------------------------------------------------------------------
  always @(posedge aclk) begin
    if (!aresetn) begin
      reg0 <= {DATA_WIDTH{1'b0}};
      reg1 <= {DATA_WIDTH{1'b0}};
      reg2 <= {DATA_WIDTH{1'b0}};
      reg3 <= {DATA_WIDTH{1'b0}};
    end else if (wr_en) begin
      case (wr_idx)
        2'd0:    reg0 <= (reg0 & ~wr_mask) | (wr_data & wr_mask);
        2'd1:    reg1 <= (reg1 & ~wr_mask) | (wr_data & wr_mask);
        2'd2:    reg2 <= (reg2 & ~wr_mask) | (wr_data & wr_mask);
        2'd3:    reg3 <= (reg3 & ~wr_mask) | (wr_data & wr_mask);
        default: reg0 <= reg0;
      endcase
    end
  end

  // -------------------------------------------------------------------------
  // Write response
  // -------------------------------------------------------------------------
  always @(posedge aclk) begin
    if (!aresetn) begin
      s_axil_bvalid <= 1'b0;
      s_axil_bresp  <= RESP_OKAY;
    end else if (do_write) begin
      s_axil_bvalid <= 1'b1;
      s_axil_bresp  <= wr_mapped ? RESP_OKAY : RESP_SLVERR;
    end else if (s_axil_bready) begin
      s_axil_bvalid <= 1'b0;
    end
  end

  // -------------------------------------------------------------------------
  // Read path
  // -------------------------------------------------------------------------
  always @* begin
    case (rd_idx)
      2'd0:    rd_word = reg0;
      2'd1:    rd_word = reg1;
      2'd2:    rd_word = reg2;
      2'd3:    rd_word = reg3;
      default: rd_word = {DATA_WIDTH{1'b0}};
    endcase
  end

  always @(posedge aclk) begin
    if (!aresetn) begin
      s_axil_rvalid <= 1'b0;
      s_axil_rresp  <= RESP_OKAY;
      s_axil_rdata  <= {DATA_WIDTH{1'b0}};
    end else if (ar_hs) begin
      s_axil_rvalid <= 1'b1;
      s_axil_rresp  <= ar_mapped ? RESP_OKAY : RESP_SLVERR;
      s_axil_rdata  <= ar_mapped ? rd_word : {DATA_WIDTH{1'b0}};
    end else if (s_axil_rready) begin
      s_axil_rvalid <= 1'b0;
    end
  end

  // -------------------------------------------------------------------------
  // Design-intent properties (read with -formal). Not proven in this task.
  // -------------------------------------------------------------------------
`ifdef FORMAL
  reg f_past_valid;
  initial f_past_valid = 1'b0;
  always @(posedge aclk) f_past_valid <= 1'b1;

  // Reset is active on the first cycle; the manager keeps VALID low in reset.
  always @(*) begin
    if (!f_past_valid) assume(!aresetn);
    if (!aresetn) begin
      assume(!s_axil_awvalid);
      assume(!s_axil_wvalid);
      assume(!s_axil_arvalid);
    end
  end

  // Manager holds VALID and payload until READY.
  always @(posedge aclk) begin
    if (f_past_valid && $past(aresetn) && aresetn) begin
      if ($past(s_axil_awvalid && !s_axil_awready)) begin
        assume(s_axil_awvalid);
        assume(s_axil_awaddr == $past(s_axil_awaddr));
      end
      if ($past(s_axil_wvalid && !s_axil_wready)) begin
        assume(s_axil_wvalid);
        assume(s_axil_wdata == $past(s_axil_wdata));
        assume(s_axil_wstrb == $past(s_axil_wstrb));
      end
      if ($past(s_axil_arvalid && !s_axil_arready)) begin
        assume(s_axil_arvalid);
        assume(s_axil_araddr == $past(s_axil_araddr));
      end
    end
  end

  always @(posedge aclk) begin
    // Responses low and half writes dropped after reset.
    if (f_past_valid && !$past(aresetn)) begin
      assert(!s_axil_bvalid);
      assert(!s_axil_rvalid);
      assert(!aw_held);
      assert(!w_held);
    end
    if (f_past_valid && $past(aresetn)) begin
      // B and R hold, with a stable payload, until taken.
      if ($past(s_axil_bvalid && !s_axil_bready)) begin
        assert(s_axil_bvalid);
        assert(s_axil_bresp == $past(s_axil_bresp));
      end
      if ($past(s_axil_rvalid && !s_axil_rready)) begin
        assert(s_axil_rvalid);
        assert(s_axil_rresp == $past(s_axil_rresp));
        assert(s_axil_rdata == $past(s_axil_rdata));
      end
      // A response is valid exactly when an accepted request awaits it.
      assert(s_axil_bvalid == ($past(do_write) ||
                               $past(s_axil_bvalid && !s_axil_bready)));
      assert(s_axil_rvalid == ($past(ar_hs) ||
                               $past(s_axil_rvalid && !s_axil_rready)));
      // Response code follows the address policy.
      if ($past(do_write))
        assert(s_axil_bresp == ($past(wr_mapped) ? RESP_OKAY : RESP_SLVERR));
      if ($past(ar_hs))
        assert(s_axil_rresp == ($past(ar_mapped) ? RESP_OKAY : RESP_SLVERR));
    end
  end

  // State invariants: at most one write open; legal response codes.
  always @(*) begin
    if (f_past_valid) begin
      if (s_axil_bvalid) begin
        assert(!aw_held);
        assert(!w_held);
      end
      assert((s_axil_bresp == RESP_OKAY) || (s_axil_bresp == RESP_SLVERR));
      assert((s_axil_rresp == RESP_OKAY) || (s_axil_rresp == RESP_SLVERR));
      if (s_axil_rresp == RESP_SLVERR)
        assert(s_axil_rdata == {DATA_WIDTH{1'b0}});
    end
  end

  always @(posedge aclk) begin
    if (f_past_valid && aresetn) begin
      cover(s_axil_bvalid && s_axil_bready && (s_axil_bresp == RESP_OKAY));
      cover(s_axil_bvalid && s_axil_bready && (s_axil_bresp == RESP_SLVERR));
      cover(s_axil_rvalid && s_axil_rready && (s_axil_rresp == RESP_OKAY));
      cover(aw_held);
      cover(w_held);
    end
  end
`endif

endmodule
=== END FILE ===
