`timescale 1ns / 1ps

`define CHECK(cond, msg) begin if (cond) passed = passed + 1; else begin failed = failed + 1; $error("FAIL: %0s at time %0t", msg, $time); end end

// ---------------------------------------------------------------------------
// Self-checking testbench for axi4_lite_regs.
// Inputs are driven, and outputs sampled, at the falling edge of aclk. DUT
// outputs depend on registered state only, so a value sampled at the falling
// edge is the value the next rising edge sees.
// ---------------------------------------------------------------------------
module axi4_lite_regs_tb;

  localparam integer ADDR_W  = 4;
  localparam integer DATA_W  = 32;
  localparam [1:0]   OKAY    = 2'b00;
  localparam [1:0]   SLVERR  = 2'b10;
  localparam integer TIMEOUT = 64;

  reg                 aclk;
  reg                 aresetn;
  reg  [ADDR_W-1:0]   s_axil_awaddr;
  reg                 s_axil_awvalid;
  wire                s_axil_awready;
  reg  [DATA_W-1:0]   s_axil_wdata;
  reg  [DATA_W/8-1:0] s_axil_wstrb;
  reg                 s_axil_wvalid;
  wire                s_axil_wready;
  wire [1:0]          s_axil_bresp;
  wire                s_axil_bvalid;
  reg                 s_axil_bready;
  reg  [ADDR_W-1:0]   s_axil_araddr;
  reg                 s_axil_arvalid;
  wire                s_axil_arready;
  wire [DATA_W-1:0]   s_axil_rdata;
  wire [1:0]          s_axil_rresp;
  wire                s_axil_rvalid;
  reg                 s_axil_rready;

  integer          passed;
  integer          failed;
  reg [8*64-1:0]   nonce;
  reg [DATA_W-1:0] model [0:3];

  integer          i;
  reg [ADDR_W-1:0] a;

  axi4_lite_regs #(
      .ADDR_WIDTH(ADDR_W),
      .DATA_WIDTH(DATA_W)
  ) dut (
      .aclk           (aclk),
      .aresetn        (aresetn),
      .s_axil_awaddr  (s_axil_awaddr),
      .s_axil_awvalid (s_axil_awvalid),
      .s_axil_awready (s_axil_awready),
      .s_axil_wdata   (s_axil_wdata),
      .s_axil_wstrb   (s_axil_wstrb),
      .s_axil_wvalid  (s_axil_wvalid),
      .s_axil_wready  (s_axil_wready),
      .s_axil_bresp   (s_axil_bresp),
      .s_axil_bvalid  (s_axil_bvalid),
      .s_axil_bready  (s_axil_bready),
      .s_axil_araddr  (s_axil_araddr),
      .s_axil_arvalid (s_axil_arvalid),
      .s_axil_arready (s_axil_arready),
      .s_axil_rdata   (s_axil_rdata),
      .s_axil_rresp   (s_axil_rresp),
      .s_axil_rvalid  (s_axil_rvalid),
      .s_axil_rready  (s_axil_rready)
  );

  initial aclk = 1'b0;
  always #5 aclk = ~aclk;

  // -------------------------------------------------------------------------
  // Reference model helpers
  // -------------------------------------------------------------------------
  function mapped(input [ADDR_W-1:0] addr_f);
    begin
      mapped = (addr_f[1:0] == 2'b00);
    end
  endfunction

  function [DATA_W-1:0] merge(input [DATA_W-1:0] old_v, input [DATA_W-1:0] new_v,
                              input [3:0] strb_v);
    integer b;
    begin
      merge = old_v;
      for (b = 0; b < 4; b = b + 1)
        if (strb_v[b]) merge[b*8 +: 8] = new_v[b*8 +: 8];
    end
  endfunction

  // -------------------------------------------------------------------------
  // Reset: checks responses low during and after reset, READY high after.
  // -------------------------------------------------------------------------
  task do_reset;
    integer k;
    begin
      @(negedge aclk);
      aresetn        = 1'b0;
      s_axil_awvalid = 1'b0;
      s_axil_wvalid  = 1'b0;
      s_axil_arvalid = 1'b0;
      s_axil_bready  = 1'b0;
      s_axil_rready  = 1'b0;
      @(negedge aclk);
      `CHECK(!s_axil_bvalid, "reset: BVALID low during reset")
      `CHECK(!s_axil_rvalid, "reset: RVALID low during reset")
      @(negedge aclk);
      aresetn = 1'b1;
      @(negedge aclk);
      `CHECK(!s_axil_bvalid && !s_axil_rvalid, "reset: responses low after reset")
      `CHECK(s_axil_awready && s_axil_wready && s_axil_arready, "reset: all READY high after reset")
      for (k = 0; k < 4; k = k + 1) model[k] = {DATA_W{1'b0}};
    end
  endtask

  // -------------------------------------------------------------------------
  // Idle cycles: no response may appear without a request.
  // -------------------------------------------------------------------------
  task idle(input integer n);
    integer k;
    begin
      for (k = 0; k < n; k = k + 1) begin
        @(negedge aclk);
        s_axil_awvalid = 1'b0;
        s_axil_wvalid  = 1'b0;
        s_axil_arvalid = 1'b0;
        `CHECK(!s_axil_bvalid && !s_axil_rvalid, "idle: no response without a request")
      end
    end
  endtask

  // -------------------------------------------------------------------------
  // One write transaction with independent AW and W delays and B stall.
  // -------------------------------------------------------------------------
  task axil_write(input [ADDR_W-1:0] addr, input [DATA_W-1:0] data, input [3:0] strb,
                  input integer aw_delay, input integer w_delay, input integer b_stall,
                  input [1:0] exp_resp);
    integer   cyc;
    integer   done_cyc;
    integer   b_seen;
    reg       aw_done;
    reg       w_done;
    reg       finished;
    reg       hold_chk;
    reg       b_first_pending;
    reg [1:0] held_resp;
    begin
      aw_done = 1'b0; w_done = 1'b0; finished = 1'b0; hold_chk = 1'b0;
      b_first_pending = 1'b1; held_resp = 2'b00;
      done_cyc = -1; b_seen = 0; cyc = 0;
      while (!finished) begin
        @(negedge aclk);
        // Observe state left by the previous rising edge.
        if (cyc == 0) begin
          `CHECK(s_axil_awready && s_axil_wready && !s_axil_bvalid, "write: channel ready at start - back-to-back")
        end
        if (s_axil_bvalid) begin
          if (done_cyc < 0) begin
            `CHECK(1'b0, "write: BVALID before both AW and W were accepted")
          end else if (b_first_pending) begin
            `CHECK((cyc - done_cyc) >= 1 && (cyc - done_cyc) <= 2, "write: latency within 2 cycles")
            `CHECK((cyc - done_cyc) == 1, "write: latency is 1 cycle")
          end
          b_first_pending = 1'b0;
          if (hold_chk) begin
            `CHECK(s_axil_bresp == held_resp, "write: BRESP stable while stalled")
          end
          `CHECK(!s_axil_awready && !s_axil_wready, "write: no AW or W accepted while B pending")
        end else if (hold_chk) begin
          `CHECK(1'b0, "write: BVALID dropped before BREADY")
        end
        // Drive. Payload is scrambled while VALID is low.
        s_axil_awvalid = !aw_done && (cyc >= aw_delay);
        s_axil_awaddr  = s_axil_awvalid ? addr : ~addr;
        s_axil_wvalid  = !w_done && (cyc >= w_delay);
        s_axil_wdata   = s_axil_wvalid ? data : ~data;
        s_axil_wstrb   = s_axil_wvalid ? strb : ~strb;
        s_axil_bready  = (b_seen >= b_stall);
        // Handshakes at the coming rising edge.
        if (s_axil_awvalid && s_axil_awready) aw_done = 1'b1;
        if (s_axil_wvalid && s_axil_wready) w_done = 1'b1;
        if (aw_done && w_done && (done_cyc < 0)) done_cyc = cyc;
        if (s_axil_bvalid && s_axil_bready) begin
          finished = 1'b1;
          `CHECK(s_axil_bresp == exp_resp, "write: BRESP matches the address policy")
        end
        hold_chk  = s_axil_bvalid && !s_axil_bready;
        held_resp = s_axil_bresp;
        if (s_axil_bvalid) b_seen = b_seen + 1;
        cyc = cyc + 1;
        if ((cyc > TIMEOUT) && !finished) begin
          `CHECK(1'b0, "write: timeout waiting for B")
          finished = 1'b1;
        end
      end
    end
  endtask

  // -------------------------------------------------------------------------
  // One read transaction with AR delay and R stall.
  // -------------------------------------------------------------------------
  task axil_read(input [ADDR_W-1:0] addr, input integer ar_delay, input integer r_stall,
                 input [DATA_W-1:0] exp_data, input [1:0] exp_resp);
    integer          cyc;
    integer          done_cyc;
    integer          r_seen;
    reg              ar_done;
    reg              finished;
    reg              hold_chk;
    reg              r_first_pending;
    reg [1:0]        held_resp;
    reg [DATA_W-1:0] held_data;
    begin
      ar_done = 1'b0; finished = 1'b0; hold_chk = 1'b0; r_first_pending = 1'b1;
      held_resp = 2'b00; held_data = {DATA_W{1'b0}};
      done_cyc = -1; r_seen = 0; cyc = 0;
      while (!finished) begin
        @(negedge aclk);
        if (cyc == 0) begin
          `CHECK(s_axil_arready && !s_axil_rvalid, "read: channel ready at start - back-to-back")
        end
        if (s_axil_rvalid) begin
          if (done_cyc < 0) begin
            `CHECK(1'b0, "read: RVALID before AR was accepted")
          end else if (r_first_pending) begin
            `CHECK((cyc - done_cyc) >= 1 && (cyc - done_cyc) <= 2, "read: latency within 2 cycles")
            `CHECK((cyc - done_cyc) == 1, "read: latency is 1 cycle")
          end
          r_first_pending = 1'b0;
          if (hold_chk) begin
            `CHECK(s_axil_rdata == held_data, "read: RDATA stable while stalled")
            `CHECK(s_axil_rresp == held_resp, "read: RRESP stable while stalled")
          end
          `CHECK(!s_axil_arready, "read: no AR accepted while R pending")
        end else if (hold_chk) begin
          `CHECK(1'b0, "read: RVALID dropped before RREADY")
        end
        s_axil_arvalid = !ar_done && (cyc >= ar_delay);
        s_axil_araddr  = s_axil_arvalid ? addr : ~addr;
        s_axil_rready  = (r_seen >= r_stall);
        if (s_axil_arvalid && s_axil_arready) begin
          ar_done  = 1'b1;
          done_cyc = cyc;
        end
        if (s_axil_rvalid && s_axil_rready) begin
          finished = 1'b1;
          `CHECK(s_axil_rresp == exp_resp, "read: RRESP matches the address policy")
          `CHECK(s_axil_rdata == exp_data, "read: RDATA matches the model")
        end
        hold_chk  = s_axil_rvalid && !s_axil_rready;
        held_resp = s_axil_rresp;
        held_data = s_axil_rdata;
        if (s_axil_rvalid) r_seen = r_seen + 1;
        cyc = cyc + 1;
        if ((cyc > TIMEOUT) && !finished) begin
          `CHECK(1'b0, "read: timeout waiting for R")
          finished = 1'b1;
        end
      end
    end
  endtask

  // -------------------------------------------------------------------------
  // Wrappers: expected values computed from the stimulus and the model.
  // -------------------------------------------------------------------------
  task write_chk(input [ADDR_W-1:0] addr, input [DATA_W-1:0] data, input [3:0] strb,
                 input integer aw_delay, input integer w_delay, input integer b_stall);
    reg [1:0] exp_r;
    begin
      exp_r = mapped(addr) ? OKAY : SLVERR;
      axil_write(addr, data, strb, aw_delay, w_delay, b_stall, exp_r);
      if (mapped(addr)) model[addr[3:2]] = merge(model[addr[3:2]], data, strb);
    end
  endtask

  task read_chk(input [ADDR_W-1:0] addr, input integer ar_delay, input integer r_stall);
    reg [DATA_W-1:0] exp_d;
    reg [1:0]        exp_r;
    begin
      if (mapped(addr)) begin
        exp_d = model[addr[3:2]];
        exp_r = OKAY;
      end else begin
        exp_d = {DATA_W{1'b0}};
        exp_r = SLVERR;
      end
      axil_read(addr, ar_delay, r_stall, exp_d, exp_r);
    end
  endtask

  task read_all;
    begin
      read_chk(4'h0, 0, 0);
      read_chk(4'h4, 0, 0);
      read_chk(4'h8, 0, 0);
      read_chk(4'hC, 0, 0);
    end
  endtask

  // -------------------------------------------------------------------------
  // Stimulus
  // -------------------------------------------------------------------------
  initial begin
    passed = 0;
    failed = 0;
    nonce  = {(8*64){1'b0}};
    aresetn        = 1'b0;
    s_axil_awaddr  = {ADDR_W{1'b0}};
    s_axil_awvalid = 1'b0;
    s_axil_wdata   = {DATA_W{1'b0}};
    s_axil_wstrb   = 4'h0;
    s_axil_wvalid  = 1'b0;
    s_axil_bready  = 1'b0;
    s_axil_araddr  = {ADDR_W{1'b0}};
    s_axil_arvalid = 1'b0;
    s_axil_rready  = 1'b0;
    for (i = 0; i < 4; i = i + 1) model[i] = {DATA_W{1'b0}};

    // 1. Reset values.
    do_reset;
    read_all;
    idle(2);

    // 2. Write then read every register.
    write_chk(4'h0, 32'h11223344, 4'hF, 0, 0, 0);
    write_chk(4'h4, 32'h55667788, 4'hF, 0, 0, 0);
    write_chk(4'h8, 32'h99AABBCC, 4'hF, 0, 0, 0);
    write_chk(4'hC, 32'hDDEEFF00, 4'hF, 0, 0, 0);
    read_all;
    idle(2);

    // 3. Byte strobes: partial and empty.
    write_chk(4'h0, 32'hA1A2A3A4, 4'b0001, 0, 0, 0);
    write_chk(4'h4, 32'hB1B2B3B4, 4'b0110, 0, 0, 0);
    write_chk(4'h8, 32'hC1C2C3C4, 4'b1000, 0, 0, 0);
    write_chk(4'hC, 32'hD1D2D3D4, 4'b0000, 0, 0, 0);
    write_chk(4'h0, 32'hE1E2E3E4, 4'b1010, 0, 0, 0);
    read_all;
    idle(2);

    // 4. AW / W ordering.
    write_chk(4'h0, 32'h01010101, 4'hF, 0, 3, 0);   // AW before W
    write_chk(4'h4, 32'h02020202, 4'hF, 4, 0, 0);   // W before AW
    write_chk(4'h8, 32'h03030303, 4'hF, 2, 2, 0);   // together after a gap
    write_chk(4'hC, 32'h04040404, 4'hF, 0, 7, 0);   // long gap
    write_chk(4'h0, 32'h05050505, 4'b0101, 6, 1, 0);
    read_all;
    idle(2);

    // 5. Back-pressure on B and R.
    write_chk(4'h4, 32'h0A0B0C0D, 4'hF, 0, 0, 5);
    write_chk(4'h8, 32'h1A1B1C1D, 4'hF, 3, 0, 4);
    read_chk(4'h4, 0, 6);
    read_chk(4'h8, 2, 3);
    idle(2);

    // 6. Back-to-back transactions.
    for (i = 0; i < 8; i = i + 1) begin
      a = {i[1:0], 2'b00};
      write_chk(a, 32'hA5000000 | i, 4'hF, 0, 0, 0);
    end
    for (i = 0; i < 8; i = i + 1) begin
      read_chk({i[1:0], 2'b00}, 0, 0);
    end
    idle(2);

    // 7. SLVERR policy for unmapped (misaligned) addresses.
    write_chk(4'h5, 32'h12345678, 4'hF, 0, 0, 0);
    write_chk(4'hE, 32'h87654321, 4'hF, 1, 0, 0);
    write_chk(4'h1, 32'hFFFFFFFF, 4'b0000, 0, 0, 2);
    write_chk(4'h3, 32'hFFFFFFFF, 4'hF, 0, 2, 0);
    read_all;                       // nothing changed
    read_chk(4'h5, 0, 0);
    read_chk(4'hE, 0, 3);
    read_chk(4'h2, 1, 0);
    read_chk(4'hF, 0, 0);
    idle(2);

    // 8. A read and a write on the same clock (different registers).
    fork
      write_chk(4'h4, 32'hCAFEBABE, 4'hF, 0, 0, 0);
      read_chk(4'h8, 0, 0);
    join
    fork
      write_chk(4'hC, 32'h0BADC0DE, 4'b1100, 0, 2, 3);
      read_chk(4'h0, 0, 4);
    join
    fork
      write_chk(4'h9, 32'h13579BDF, 4'hF, 0, 0, 0);
      read_chk(4'hD, 0, 0);
    join
    read_all;
    idle(2);

    // 9. Reset during traffic.
    // 9a. AW accepted without W, then reset: the half write is dropped.
    @(negedge aclk);
    `CHECK(s_axil_awready && s_axil_wready, "half AW: channel ready before AW")
    s_axil_awaddr  = 4'h8;
    s_axil_awvalid = 1'b1;
    s_axil_wvalid  = 1'b0;
    @(negedge aclk);
    s_axil_awvalid = 1'b0;
    `CHECK(!s_axil_awready && s_axil_wready && !s_axil_bvalid, "half AW: address held and waiting for W")
    do_reset;
    write_chk(4'h4, 32'h0BADF00D, 4'hF, 3, 0, 0);   // W first: stale AW would fire early
    read_all;
    idle(2);

    // 9b. W accepted without AW, then reset.
    @(negedge aclk);
    s_axil_wdata   = 32'hFFFFFFFF;
    s_axil_wstrb   = 4'hF;
    s_axil_wvalid  = 1'b1;
    s_axil_awvalid = 1'b0;
    @(negedge aclk);
    s_axil_wvalid = 1'b0;
    `CHECK(!s_axil_wready && s_axil_awready && !s_axil_bvalid, "half W: data held and waiting for AW")
    do_reset;
    write_chk(4'h8, 32'h00C0FFEE, 4'b0011, 0, 3, 0); // AW first: stale W would fire early
    read_all;
    idle(2);

    // 9c. B and R pending under back-pressure, then reset.
    @(negedge aclk);
    `CHECK(s_axil_awready && s_axil_wready && s_axil_arready, "pending: channels ready before requests")
    s_axil_bready  = 1'b0;
    s_axil_rready  = 1'b0;
    s_axil_awaddr  = 4'h0;
    s_axil_awvalid = 1'b1;
    s_axil_wdata   = 32'h12345678;
    s_axil_wstrb   = 4'hF;
    s_axil_wvalid  = 1'b1;
    s_axil_araddr  = 4'h8;
    s_axil_arvalid = 1'b1;
    @(negedge aclk);
    s_axil_awvalid = 1'b0;
    s_axil_wvalid  = 1'b0;
    s_axil_arvalid = 1'b0;
    `CHECK(s_axil_bvalid && s_axil_rvalid, "pending: B and R valid one cycle after requests")
    @(negedge aclk);
    `CHECK(s_axil_bvalid && s_axil_rvalid, "pending: B and R held under back-pressure")
    do_reset;
    read_all;                       // all registers back to zero
    idle(2);

    if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = {(8*64){1'b0}};
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
    $finish;
  end

endmodule

